// lib
using MessagePack;

namespace Lib
{
    // First keyed member uses an int key, so the collector settles on isIntKey = true.
    // The second member uses a string key: intKey == null while isIntKey is true.
    // On the source-generator path (reportDiagnostic is null) the old collector goes on
    // to read intKey!.Value and throws InvalidOperationException; the new one skips the member.
    [MessagePackObject]
    public class Mixed
    {
        [Key(0)]
        public int Id { get; set; }

        [Key("name")]
        public string Name { get; set; }
    }
}

// app
using System;
using Lib;

namespace App
{
    public static class Program
    {
        public static void Main()
        {
            var value = new Mixed { Id = 1, Name = "a" };
            Console.WriteLine(value.Id + ":" + value.Name);
        }
    }
}
